from taf.nms.nsp.nfmp.interfaces.nfmp19 import Nfmp19
from taf.nms.nsp.nfmp.exception import NfmpVersionNotSupported


class SupportedNfmpVersions(object):
    by_latest = [Nfmp19]


class NfmpProvider(object):
    """
    Class to choose NFMP by version and provide related interfaces
    """

    @classmethod
    def discover_nfmp(cls, ip, username, password, port, nfmp_version=19):
        """
        To find target NFMP by nfmp_version
        """
        for nfmp in SupportedNfmpVersions.by_latest:
            if str(nfmp_version).lower() == str(nfmp.NFMP_VERSION).lower():
                return nfmp(ip, username, password, port)
        raise NfmpVersionNotSupported("Requested NFMP version {} is not supported.".format(nfmp_version))
